// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }

    function testFuzz_property(address proposedAddress, string memory typeStr) public {
        vm.assume(proposedAddress != address(0));

        c.init(address(0x1), address(0x2), address(0x3));

        uint pidBefore = c.proposalCount();
        vm.prank(address(0x1000));
        c.newAddressProposal(proposedAddress, typeStr);
        uint pidAfter = c.proposalCount();

        uint proposalID = pidAfter;
        assertTrue(
            c.mapPID_address(proposalID) == proposedAddress,
            "mapPID_address must equal the passed proposedAddress"
        );
    }
}
